use crate::error::AppError;
use crate::persistence::product_book_repo::ProductBookSource;
use rquickjs::{Context, Function, Object, Runtime};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use sqlx::SqlitePool;
use std::sync::{Arc, OnceLock};
use std::time::{Duration, Instant};

// Generated by scripts/build-product-book-renderer from the same source used
// by desktop exports. No filesystem, network, or process APIs are installed.
const RENDERER: &str = include_str!("../../resources/product_book_renderer.js");
const MAX_INPUT_BYTES: usize = 64 * 1024 * 1024;
const MAX_RUNTIME_BYTES: usize = 256 * 1024 * 1024;
const MAX_RENDER_TIME: Duration = Duration::from_secs(30);
static RENDER_SLOTS: OnceLock<Arc<tokio::sync::Semaphore>> = OnceLock::new();

#[derive(Clone, Copy, Debug, Deserialize, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum ProductBookFormat { Docs, Book }

#[derive(Clone, Copy, Debug, Deserialize, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum ProductBookRenderMode { Web, Print, Epub }

#[derive(Clone, Copy, Debug, Deserialize, Serialize)]
pub enum ProductBookTrim {
    #[serde(rename = "trade-6x9")]
    Trade,
    #[serde(rename = "a5")]
    A5,
    #[serde(rename = "us-letter")]
    UsLetter,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct RenderRequest<'a> {
    source: &'a ProductBookSource,
    format: ProductBookFormat,
    render_mode: ProductBookRenderMode,
    trim_preset: ProductBookTrim,
}

/// Limit concurrent snapshots and runtimes, and keep CPU work off async workers.
pub async fn render_product_book_for_product(pool: &SqlitePool, product_id: &str, format: ProductBookFormat, render_mode: ProductBookRenderMode, trim_preset: ProductBookTrim) -> Result<Value, AppError> {
    if matches!(format, ProductBookFormat::Docs) && !matches!(render_mode, ProductBookRenderMode::Web) {
        return Err(AppError::Validation("Docs output supports web mode only".into()));
    }
    let permit = RENDER_SLOTS.get_or_init(|| Arc::new(tokio::sync::Semaphore::new(2)))
        .clone().acquire_owned().await.map_err(|_| AppError::Internal("Product Book renderer unavailable".into()))?;
    let source = crate::persistence::product_book_repo::get_product_book_source(pool, product_id).await?;
    tokio::task::spawn_blocking(move || {
        let _permit = permit;
        let mut result = render_product_book(&source, format, render_mode, trim_preset)?;
        result.as_object_mut().ok_or_else(|| AppError::Internal("Product Book renderer returned invalid output".into()))?
            .insert("productName".into(), Value::String(source.tree.product.name.clone()));
        Ok(result)
    }).await.map_err(|e| AppError::Internal(format!("Product Book renderer task failed: {e}")))?
}

pub fn render_product_book(source: &ProductBookSource, format: ProductBookFormat, render_mode: ProductBookRenderMode, trim_preset: ProductBookTrim) -> Result<Value, AppError> {
    if matches!(format, ProductBookFormat::Docs) && !matches!(render_mode, ProductBookRenderMode::Web) {
        return Err(AppError::Validation("Docs output supports web mode only".into()));
    }
    let request = serde_json::to_string(&RenderRequest { source, format, render_mode, trim_preset })?;
    render_request(&request)
}

fn render_request(request: &str) -> Result<Value, AppError> {
    if request.len() > MAX_INPUT_BYTES {
        return Err(AppError::Validation("Product Book source exceeds the renderer input limit".into()));
    }
    let runtime = Runtime::new().map_err(|e| AppError::Internal(format!("Product Book runtime unavailable: {e}")))?;
    runtime.set_memory_limit(MAX_RUNTIME_BYTES);
    runtime.set_max_stack_size(1024 * 1024);
    let deadline = Instant::now() + MAX_RENDER_TIME;
    runtime.set_interrupt_handler(Some(Box::new(move || Instant::now() >= deadline)));
    let context = Context::full(&runtime).map_err(|e| AppError::Internal(format!("Product Book context unavailable: {e}")))?;
    let output: String = context.with(|ctx| {
        ctx.eval::<(), _>(RENDERER)?;
        let api: Object = ctx.globals().get("AruviProductBook")?;
        let function: Function = api.get("renderJson")?;
        function.call((request,))
    }).map_err(|e| AppError::Internal(format!("Product Book rendering failed: {e}")))?;
    serde_json::from_str(&output).map_err(Into::into)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn rejects_oversized_input_before_starting_runtime() {
        assert!(matches!(render_request(&" ".repeat(MAX_INPUT_BYTES + 1)), Err(AppError::Validation(_))));
    }

    #[test]
    #[ignore = "requires a fixture captured from the desktop Product Book UI"]
    fn embedded_renderer_matches_desktop_output() {
        let fixture_path = std::env::var("ARUVI_BOOK_PARITY_FIXTURE_PATH").expect("fixture path required");
        let fixture: Value = serde_json::from_slice(&std::fs::read(fixture_path).unwrap()).unwrap();
        for (label, format, mode) in [("Docs HTML", "docs", "web"), ("Book HTML", "book", "web"), ("EPUB", "book", "epub"), ("PDF", "book", "print")] {
            let request = serde_json::json!({ "source": fixture["source"], "format": format, "renderMode": mode, "trimPreset": "trade-6x9" });
            let actual = render_request(&request.to_string()).unwrap();
            let expected_html = fixture["renderedVariants"][label].as_str().unwrap();
            let actual_html = actual["html"].as_str().unwrap();
            assert_eq!(remove_generation_time(actual_html, format), remove_generation_time(expected_html, format), "{label} differs from desktop");
        }
    }

    fn remove_generation_time(html: &str, format: &str) -> String {
        let pattern = if format == "docs" { r"Generated by Aruvi Studio on ([^<]+)\.</div>" } else { r"<strong>Generated</strong>([^<]+)</div>" };
        let regex = regex::Regex::new(pattern).unwrap();
        let timestamp = regex.captures(html).expect("generated timestamp present").get(1).unwrap().as_str();
        html.replace(timestamp, "[generation time]")
    }
}
